Task: Pick up the red cube and hold it at least 5 cm above the table.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Pick up the red cube and hold it at least 5 cm above the table."""
  5|     try:
  6|         # Start from a known safe pose
  7|         robot.home()
  8|         
  9|         max_attempts = 2
 10|         grasped = False
 11|         cx = cy = cz = None  # placeholders for the final successful perception
 12|         
 13|         for _ in range(max_attempts):
 14|             obs = robot.observe()
 15|             cube_info = obs["objects"].get("red_cube")
 16|             if cube_info is None:
 17|                 # Cannot see the cube – abort this attempt
 18|                 continue
 19|             cx, cy, cz = cube_info["pos"]
 20|             
 21|             # Tool point height that gives ample clearance above the cube
 22|             grasp_z = cz + 0.04          # tool point ~4 cm above cube centre
 23|             approach_z = grasp_z + 0.025 # 2.5 cm clearance above the grasp point
 24|             
 25|             # 1. Move to approach pose
 26|             try:
 27|                 robot.move_to(cx, cy, approach_z, speed=0.1)
 28|             except MotionError:
 29|                 continue  # try next attempt after re‑observing
 30|             
 31|             # 2. Descend to grasp position
 32|             try:
 33|                 robot.move_to(cx, cy, grasp_z, speed=0.05)
 34|             except MotionError:
 35|                 continue
 36|             
 37|             # 3. Close the gripper
 38|             grasped = robot.grasp()
 39|             if grasped:
 40|                 break  # successful grasp, exit retry loop
 41|             else:
 42|                 # Grasp failed – retreat a bit and try again (with fresh observation)
 43|                 try:
 44|                     robot.move_by(dz=0.02, speed=0.05)
 45|                 except MotionError:
 46|                     pass
 47|                 # loop will re‑observe at the top
 48|         
 49|         if not grasped:
 50|             return False  # exhausted attempts without a grasp
 51|         
 52|         # 4. Lift the cube so its centre is at least 5 cm above the table.
 53|         #    Constant tool‑point height that guarantees cube centre ≥ 0.065 m.
 54|         target_z = 0.0775
 55|         try:
 56|             robot.move_to(cx, cy, target_z, speed=0.1)
 57|         except MotionError:
 58|             robot.release()
 59|             return False
 60|         
 61|         # Apply a small upward push to help maintain grip, then verify hold.
 62|         try:
 63|             robot.move_by(dz=0.01, speed=0.05)
 64|         except MotionError:
 65|             pass
 66|         
 67|         # 5. Verify that we are still holding the cube
 68|         if robot.holding() == "red_cube":
 69|             return True
 70|         else:
 71|             robot.release()
 72|             return False
 73|     
 74|     except MotionError:
 75|         return False
 76|     except Exception as e:
 77|         robot.log("Exception in run:", e)
 78|         return False

